  ]);
});

test('returns every distinct word when n exceeds their number', () => {
  assert.deepEqual(topWords('pear apple', 99), [
    { word: 'apple', count: 1 },
    { word: 'pear', count: 1 },
  ]);
});

test('throws a RangeError naming the function for an invalid n', () => {
